  for(int i=1;i<=8;i++)foreach(var side in new[]{"Object","Target"})Check(service.Bind(new(ConfigurationSubscriptionDomain.Combination,CameraMappingPlugin.PointInputName(side,i),"POINT"),Binding(side+"Array"+((i-1)%2+1))).Status==ConfigurationSubscriptionStatus.Available,"all source-declared point groups bind actual alias leaves: "+side+i);var allValues=Flow().Nodes.Single(n=>n.Id==targetId).Parameters.ToDictionary(p=>p.Key,p=>p.Value.Clone());for(int i=3;i<=8;i++)allValues["Data"+i]=JsonSerializer.SerializeToElement("Data"+i+"#1");document.SetProcedureNodeParameters(procedure,targetId,allValues);run=new GraphExecutor(modules).RunAsync(Flow(),output,scope:scope).GetAwaiter().GetResult();resultNode=run.Nodes.Single(n=>n.NodeId==targetId);Check(resultNode.Status==NodeRunStatus.Success&&Math.Abs(resultNode.Outputs["ScaleX"].As<double>()-2)<.003,"all eight source-named groups execute sixteen point pairs through actual graph");
